    engine = engines.get()
    try:
        b = engine.get_hub_breakdown(hub_id)
    except UnknownHub as exc:
        raise HTTPException(status_code=404, detail=exc.args[0]) from None
    return {**b.model_dump(mode="json"), "data_sources": engine.data_sources()}

