                       scores={m: self._cell(h, m) for m in metrics}) for h in hub_ids]
    most = {m: verdict({r.hub_id: r.scores[m].score for r in rows}) for m in metrics}
    return Comparison(metrics=metrics, rows=rows, most_exposed=most)

